// Checks the reader and API against data files generated by the original awstats.pl (testdata/build.sh).
const test = require('node:test');
const assert = require('node:assert');
const path = require('path');
process.env.AWSTATS_DATA_DIR = path.join(__dirname, '../testdata/data');
process.env.AWSTATS_CONF_DIR = path.join(__dirname, '../testdata/conf');
const { api } = require('../server/index.js');
const { forecast } = require('../server/forecast.js');
const q = s => new URLSearchParams(s);

test('daily visits add up to the monthly total AWStats stored', async () => {
  for (const [site, months] of Object.entries(await api(['sites'], q('')))) for (const m of months) {
    const s = await api([site, 'summary'], q(`from=${m}&to=${m}`));
    assert.strictEqual(s.sections.DAY.reduce((a, d) => a + d.visits, 0), s.general.TotalVisits, `${site} ${m}`);
  }
});

test('range summary sums months and labels ids', async () => {
  const sites = await api(['sites'], q(''));
  const all = sites.apache;
  const total = (await Promise.all(all.map(m => api(['apache', 'summary'], q(`from=${m}&to=${m}`))))).reduce((a, s) => a + s.general.TotalVisits, 0);
  const r = await api(['apache', 'summary'], q(`from=${all[0]}&to=${all.at(-1)}`));
  assert.strictEqual(r.general.TotalVisits, total);
  assert.ok(r.sections.OS.rows.every(o => o.label));
  assert.ok(r.sections.BROWSER.rows.some(b => b.group === 'Google Chrome'));
});

test('host search and IP detail from logs incl. rotated .gz', async () => {
  const host = (await api(['nginx', 'list', 'VISITOR'], q(''))).rows[0].host;
  const l = await api(['nginx', 'list', 'VISITOR'], q(`q=${host}`));
  assert.ok(l.rows.some(r => r.host === host));
  const d = await api(['nginx', 'ip', host], q(''));
  assert.ok(d.months.length > 0);
  assert.deepStrictEqual(d.log.files.sort(), ['nginx-access.log', 'nginx-access.log.1.gz']);
  assert.ok(d.log.total > 0 && d.log.hits.every(h => h.url));
});

test('input validation', async () => {
  await assert.rejects(api(['nope', 'summary'], q('')), /unknown site/);
  await assert.rejects(api(['apache', 'summary'], q('from=x')), /YYYYMM/);
  await assert.rejects(api(['apache', 'ip', '../etc/passwd'], q('')), /bad ip/);
  await assert.rejects(api(['apache', 'list', 'x;y'], q('')), /bad section/);
});

test('forecast follows a weekly pattern with trend', () => {
  const y = Array.from({ length: 70 }, (_, i) => 100 + i + (i % 7 >= 5 ? -40 : 0));
  const f = forecast(y, 7);
  const expect = Array.from({ length: 7 }, (_, k) => 100 + 70 + k + ((70 + k) % 7 >= 5 ? -40 : 0));
  f.mean.forEach((v, i) => assert.ok(Math.abs(v - expect[i]) < 5, `day ${i}: ${v} vs ${expect[i]}`));
  assert.strictEqual(forecast([1, 2, 3], 7), null);
});

test('unreadable or corrupt rotated logs are skipped, not fatal', async () => {
  const fs = require('fs'), os = require('os');
  const { searchIp } = require('../server/logsearch.js');
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'awng-'));
  fs.writeFileSync(path.join(dir, 'a.log'), '1.2.3.4 - - [01/Nov/2026:00:00:00 +0000] "GET / HTTP/1.1" 200 5 "-" "x"\n');
  fs.writeFileSync(path.join(dir, 'a.log.1.gz'), 'not gzip');
  const r = await searchIp([path.join(dir, 'a.log.1.gz'), path.join(dir, 'missing.gz'), path.join(dir, 'a.log')], '1.2.3.4');
  assert.strictEqual(r.total, 1);
  assert.strictEqual(r.skipped.length, 2);
});

test('a hostile request line does not stall the IP search', async () => {
  const fs = require('fs'), os = require('os');
  const { searchIp } = require('../server/logsearch.js');
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'awng-'));
  // unterminated request line: the old pattern backtracked quadratically on it (about 2 s at 40k chars)
  fs.writeFileSync(path.join(dir, 'a.log'), `1.2.3.4 - - [01/Nov/2026:00:00:00 +0000] "GET /${'a'.repeat(40000)}\n` +
    '1.2.3.4 - - [01/Nov/2026:00:00:01 +0000] "GET /x HTTP/1.1" 404 - "-" "y"\n');
  const t = Date.now();
  const r = await searchIp([path.join(dir, 'a.log')], '1.2.3.4');
  assert.ok(Date.now() - t < 200, `took ${Date.now() - t} ms`);
  assert.strictEqual(r.hits[0].raw.length > 40000, true);
  assert.deepStrictEqual([r.hits[1].url, r.hits[1].status], ['/x', 404]);
});

test('the API only answers to localhost, IP addresses and allowed host names', async () => {
  const { server, hostAllowed } = require('../server/index.js');
  for (const h of ['localhost:3000', '127.0.0.1:3000', '[::1]:3000', '10.0.0.5']) assert.ok(hostAllowed(h), h);
  for (const h of ['rebind.attacker.example', 'stats.example.com', '', undefined]) assert.ok(!hostAllowed(h), String(h));
  await new Promise(r => server.listen(0, '127.0.0.1', r));
  const get = host => new Promise((resolve, reject) => require('http').get({ port: server.address().port, path: '/api/sites', headers: { host } }, res => { res.resume(); resolve(res.statusCode); }).on('error', reject));
  try {
    assert.strictEqual(await get('localhost'), 200);
    assert.strictEqual(await get('rebind.attacker.example'), 403);
  } finally { server.close(); }
});
